-- Immutable snapshot of diagnostic questionnaire version 1.
INSERT INTO survey_versions (survey_id,version,definition_json) VALUES ('diagnostico-socioambiental',1,'{"id":"diagnostico-socioambiental","version":1,"sections":[{"id":"previo","title":"Conhecimento prévio"},{"id":"habitos","title":"Hábitos de consumo"},{"id":"socioambiental","title":"Conhecimento socioambiental"},{"id":"percepcoes","title":"Percepções e interesses"}],"questions":[{"id":"q01","section":"previo","title":"Antes desta pesquisa, você já conhecia A História das Coisas, de Annie Leonard?","type":"single","options":["Nunca ouvi falar.","Apenas conhecia o nome.","Já assisti ao vídeo.","Já li o livro.","Conheço o vídeo e o livro."]},{"id":"q02","section":"previo","title":"De 0 a 10, como você avalia seu conhecimento sobre os impactos ambientais e sociais dos produtos que consumimos?","type":"scale","min":0,"max":10},{"id":"q03","section":"habitos","title":"Com que frequência você compra produtos que não havia planejado comprar?","type":"single","options":["Nunca.","Raramente.","Às vezes.","Frequentemente.","Sempre."]},{"id":"q04","section":"habitos","title":"Quais fatores mais influenciam suas decisões de compra? (Selecionar até três.)","type":"multiple","options":["Preço.","Necessidade.","Marca.","Publicidade.","Durabilidade.","Impacto ambiental.","Condições de produção.","Outros."],"maxSelections":3},{"id":"q05","section":"habitos","title":"Quando um produto apresenta defeito, qual costuma ser sua primeira atitude?","type":"single","options":["Tentar consertar.","Avaliar o custo do conserto.","Substituir.","Guardar sem utilizar.","Depende do produto."]},{"id":"q06","section":"habitos","title":"O que você costuma fazer com produtos que não utiliza mais? (Permitir múltiplas respostas.)","type":"multiple","options":["Doar.","Vender.","Reutilizar.","Encaminhar para reciclagem.","Descartar no lixo comum.","Guardar.","Outros."]},{"id":"q07","section":"habitos","title":"Qual é a maior dificuldade para adotar hábitos de consumo mais sustentáveis?","type":"single","options":["Preço.","Falta de informações.","Poucas alternativas disponíveis.","Falta de tempo.","Hábitos pessoais.","Não encontro dificuldades.","Outros."]},{"id":"q08","section":"socioambiental","title":"Qual das seguintes atitudes pode diminuir a necessidade de extrair novas matérias-primas?","type":"single","options":["Consertar produtos e prolongar sua vida útil.","Substituir produtos que ainda funcionam.","Descartar produtos com maior frequência.","Não sei."]},{"id":"q09","section":"socioambiental","title":"A fabricação de um produto pode causar impactos ambientais e sociais antes mesmo de ele ser utilizado?","type":"single","options":["Sim, devido ao uso de recursos, à produção e às condições de trabalho.","Não, os impactos começam apenas após a compra.","Não, se o produto for reciclável.","Não sei."]},{"id":"q10","section":"socioambiental","title":"Qual das seguintes informações ajuda a avaliar os impactos ambientais da distribuição de um produto?","type":"single","options":["Meios de transporte utilizados e distâncias percorridas.","Apenas a aparência da embalagem.","Apenas a popularidade da marca.","Não sei."]},{"id":"q11","section":"socioambiental","title":"Qual atitude melhor representa uma decisão de consumo responsável?","type":"single","options":["Avaliar a necessidade da compra, a durabilidade e os impactos do produto.","Comprar sempre que houver uma promoção.","Priorizar a quantidade de produtos adquiridos.","Não sei."]},{"id":"q12","section":"socioambiental","title":"Como devem ser encaminhados equipamentos eletrônicos que não podem mais ser utilizados?","type":"single","options":["Para pontos de coleta ou sistemas apropriados de logística reversa.","Sempre para o lixo doméstico comum.","Para descarte em terrenos vazios.","Não sei."]},{"id":"q13","section":"percepcoes","title":"Quem você considera responsável pela redução dos impactos ambientais e sociais associados ao consumo?","type":"single","options":["Consumidores.","Empresas.","Governos.","Organizações sociais.","Responsabilidade compartilhada.","Não sei."]},{"id":"q14","section":"percepcoes","title":"Sobre qual assunto você gostaria de aprender mais?","type":"single","options":["Consumismo e publicidade.","Produção e meio ambiente.","Direitos dos trabalhadores.","Descarte e reciclagem.","Alternativas de consumo.","Responsabilidade das empresas e governos."]}]}');
